CREATE TABLE shedlock(name VARCHAR(64) NOT NULL,lock_until TIMESTAMP(3) NOT NULL,locked_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),locked_by VARCHAR(255) NOT NULL,PRIMARY KEY(name));
CREATE TABLE payment_reconciliation_issue(id BIGINT NOT NULL AUTO_INCREMENT,payment_id BIGINT NOT NULL,issue_type VARCHAR(50) NOT NULL,detail VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',detected_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),resolved_at TIMESTAMP(6) NULL,PRIMARY KEY(id),CONSTRAINT uk_payment_reconciliation_issue UNIQUE(payment_id,issue_type),CONSTRAINT fk_reconciliation_payment FOREIGN KEY(payment_id) REFERENCES payment_records(id));
